	'«Forgot password» works by code on all sites when a channel is on. Client sign-up in the cabinet uses the same channel.' => ['kz' => '«Парольді ұмыттым» барлық сайтта код арқылы жұмыс істейді (арна қосулы болса). Клиент кабинетінде тіркелу де осы арнамен жүреді.', 'en' => '«Forgot password» works by code on all sites when a channel is on. Client sign-up in the cabinet uses the same channel.', 'ru' => '«Забыл пароль» на всех сайтах работает через код (если канал включён). Регистрация клиента в кабинете идёт через этот же канал.', 'uz' => '«Parolni unutdim» barcha saytlarda kod orqali ishlaydi (kanal yoqilgan bo\'lsa). Mijoz kabinetida ro\'yxatdan o\'tish ham shu kanal orqali.', 'ky' => '«Сырсөздү унуттум» бардык сайттарда код аркылуу иштейт (канал күйүк болсо). Кардар кабинетинде катталуу да ушул канал менен.'],
	'Cannot write config/wa_conf.php in the admin folder. Give the folder write permission.' => ['kz' => 'Админ папкасындағы config/wa_conf.php файлына жазу мүмкін емес. Папкаға жазу рұқсатын беріңіз.', 'en' => 'Cannot write config/wa_conf.php in the admin folder. Give the folder write permission.', 'ru' => 'Нельзя записать config/wa_conf.php в папке админки. Дайте права на запись.', 'uz' => 'Admin papkasidagi config/wa_conf.php fayliga yozib bo\'lmaydi. Papkaga yozish ruxsatini bering.', 'ky' => 'Админ папкасындагы config/wa_conf.php файлына жазуу мүмкүн эмес. Папкага жазуу уруксатын бериңиз.'],
	'Check' => ['kz' => 'Тексеру', 'en' => 'Check', 'ru' => 'Проверка', 'uz' => 'Tekshirish', 'ky' => 'Текшерүү'],
	'Sends a test code to this number with the saved settings.' => ['kz' => 'Сақталған баптаумен осы нөмірге тест код жібереді.', 'en' => 'Sends a test code to this number with the saved settings.', 'ru' => 'Отправляет тестовый код на этот номер с сохранёнными настройками.', 'uz' => 'Saqlangan sozlamalar bilan shu raqamga test kod yuboradi.', 'ky' => 'Сакталган жөндөө менен ушул номерге тест код жөнөтөт.'],
	'Send' => ['kz' => 'Жіберу', 'en' => 'Send', 'ru' => 'Отправить', 'uz' => 'Yuborish', 'ky' => 'Жөнөтүү'],
	'Passwords' => ['kz' => 'Парольдер', 'en' => 'Passwords', 'ru' => 'Пароли', 'uz' => 'Parollar', 'ky' => 'Сырсөздөр'],
	'Passwords are stored with bcrypt. Old plain passwords are encrypted when the person signs in. Plain passwords left in the database:' => ['kz' => 'Парольдер bcrypt-пен сақталады. Ескі ашық парольдер адам кірген кезде өзі шифрланады. Базада әлі ашық тұрған пароль саны:', 'en' => 'Passwords are stored with bcrypt. Old plain passwords are encrypted when the person signs in. Plain passwords left in the database:', 'ru' => 'Пароли хранятся в bcrypt. Старые открытые пароли шифруются при входе человека. Открытых паролей в базе осталось:', 'uz' => 'Parollar bcrypt bilan saqlanadi. Eski ochiq parollar odam kirganda o\'zi shifrlanadi. Bazada qolgan ochiq parollar soni:', 'ky' => 'Сырсөздөр bcrypt менен сакталат. Эски ачык сырсөздөр адам киргенде өзү шифрленет. Базада калган ачык сырсөздөр:'],
	'You can encrypt them all now. This cannot be undone, so back up the database first.' => ['kz' => 'Бәрін қазір шифрлауға болады. Бұл қайтарылмайды, сондықтан алдымен базаның көшірмесін алыңыз.', 'en' => 'You can encrypt them all now. This cannot be undone, so back up the database first.', 'ru' => 'Можно зашифровать все сейчас. Это необратимо, поэтому сначала сделайте копию базы.', 'uz' => 'Hammasini hozir shifrlash mumkin. Bu qaytarilmaydi, shuning uchun avval bazaning nusxasini oling.', 'ky' => 'Баарын азыр шифрлесе болот. Бул кайтарылбайт, ошондуктан алгач базанын көчүрмөсүн алыңыз.'],
	'Encrypt all now' => ['kz' => 'Барлығын қазір шифрлау', 'en' => 'Encrypt all now', 'ru' => 'Зашифровать все сейчас', 'uz' => 'Hammasini hozir shifrlash', 'ky' => 'Баарын азыр шифрлөө'],
	'Sending...' => ['kz' => 'Жіберіліп жатыр...', 'en' => 'Sending...', 'ru' => 'Отправляется...', 'uz' => 'Yuborilmoqda...', 'ky' => 'Жөнөтүлүүдө...'],
	'Encrypt all plain passwords? Is the database backed up?' => ['kz' => 'Барлық ашық парольдерді шифрлаймыз ба? Базаның көшірмесі алынды ма?', 'en' => 'Encrypt all plain passwords? Is the database backed up?', 'ru' => 'Зашифровать все открытые пароли? Копия базы сделана?', 'uz' => 'Barcha ochiq parollarni shifrlaymizmi? Baza nusxasi olinganmi?', 'ky' => 'Бардык ачык сырсөздөрдү шифрлейбизби? Базанын көчүрмөсү алындыбы?'],
	'Test mode works only locally (the code is shown on screen)' => ['kz' => 'Тест режимі тек локалда (код экранда көрінеді)', 'en' => 'Test mode works only locally (the code is shown on screen)', 'ru' => 'Тестовый режим только локально (код виден на экране)', 'uz' => 'Test rejimi faqat lokalda (kod ekranda ko\'rinadi)', 'ky' => 'Тест режими локалда гана (код экранда көрүнөт)'],
	'Could not write config/wa_conf.php' => ['kz' => 'config/wa_conf.php файлына жазу мүмкін болмады', 'en' => 'Could not write config/wa_conf.php', 'ru' => 'Не удалось записать config/wa_conf.php', 'uz' => 'config/wa_conf.php fayliga yozib bo\'lmadi', 'ky' => 'config/wa_conf.php файлына жазуу мүмкүн болбоду'],
	'Enter the full number' => ['kz' => 'Нөмірді толық жазыңыз', 'en' => 'Enter the full number', 'ru' => 'Введите номер полностью', 'uz' => 'Raqamni to\'liq yozing', 'ky' => 'Номерди толук жазыңыз'],
	'The channel is off. Choose a channel and save first' => ['kz' => 'Арна өшірулі. Алдымен арнаны таңдап, сақтаңыз', 'en' => 'The channel is off. Choose a channel and save first', 'ru' => 'Канал выключен. Сначала выберите канал и сохраните', 'uz' => 'Kanal o\'chirilgan. Avval kanalni tanlab, saqlang', 'ky' => 'Канал өчүк. Адегенде каналды тандап, сактаңыз'],
	'Too many tests. Try in 15 minutes' => ['kz' => 'Тым көп тест. 15 минуттан кейін', 'en' => 'Too many tests. Try in 15 minutes', 'ru' => 'Слишком много тестов. Через 15 минут', 'uz' => 'Juda ko\'p test. 15 daqiqadan keyin', 'ky' => 'Өтө көп тест. 15 мүнөттөн кийин'],
	'Test mode: code %s (not sent anywhere)' => ['kz' => 'Тест режимі: код %s (ешқайда жіберілмеді)', 'en' => 'Test mode: code %s (not sent anywhere)', 'ru' => 'Тестовый режим: код %s (никуда не отправлен)', 'uz' => 'Test rejimi: kod %s (hech qayerga yuborilmadi)', 'ky' => 'Тест режими: код %s (эч жакка жөнөтүлгөн жок)'],
	'Sent. Check WhatsApp, code: %s' => ['kz' => 'Жіберілді. WhatsApp-ты тексеріңіз, код: %s', 'en' => 'Sent. Check WhatsApp, code: %s', 'ru' => 'Отправлено. Проверьте WhatsApp, код: %s', 'uz' => 'Yuborildi. WhatsApp-ni tekshiring, kod: %s', 'ky' => 'Жөнөтүлдү. WhatsApp-ты текшериңиз, код: %s'],
	'Not sent.' => ['kz' => 'Жіберілмеді.', 'en' => 'Not sent.', 'ru' => 'Не отправлено.', 'uz' => 'Yuborilmadi.', 'ky' => 'Жөнөтүлгөн жок.'],
	'Check the settings' => ['kz' => 'Баптауды тексеріңіз', 'en' => 'Check the settings', 'ru' => 'Проверьте настройки', 'uz' => 'Sozlamalarni tekshiring', 'ky' => 'Жөндөөнү текшериңиз'],
	'Encrypted: %d' => ['kz' => 'Шифрланды: %d', 'en' => 'Encrypted: %d', 'ru' => 'Зашифровано: %d', 'uz' => 'Shifrlandi: %d', 'ky' => 'Шифрленди: %d'],
	'Once per company, only for a new company with no payments' => ['kz' => 'Әр компанияға бір рет, тек төлемі жоқ жаңа компанияға', 'en' => 'Once per company, only for a new company with no payments', 'ru' => 'Один раз на компанию, только для новой компании без оплат', 'uz' => 'Har bir kompaniyaga bir marta, faqat to\'lovi yo\'q yangi kompaniyaga', 'ky' => 'Ар бир компанияга бир жолу, төлөмү жок жаңы компанияга гана'],
	'Chosen as a tariff when a company is registered or paid. Given once per company: not again after a trial, a payment or a set subscription. The paid period starts after the trial.' => ['kz' => 'Компания тіркегенде не төлем енгізгенде тариф ретінде таңдалады. Әр компанияға бір рет: сынақ, төлем не жазылым мерзімі болған компанияға берілмейді. Ақылы мерзім сынақ біткен соң басталады.', 'en' => 'Chosen as a tariff when a company is registered or paid. Given once per company: not again after a trial, a payment or a set subscription. The paid period starts after the trial.', 'ru' => 'Выбирается как тариф при регистрации компании или вводе оплаты. Один раз на компанию: не даётся, если уже был пробный период, оплата или срок подписки. Платный период начинается после пробного.', 'uz' => 'Kompaniya ro\'yxatdan o\'tkazilganda yoki to\'lov kiritilganda tarif sifatida tanlanadi. Har bir kompaniyaga bir marta: sinov, to\'lov yoki obuna muddati bo\'lgan kompaniyaga berilmaydi. Pullik muddat sinovdan keyin boshlanadi.', 'ky' => 'Компания катталганда же төлөм киргизилгенде тариф катары тандалат. Ар бир компанияга бир жолу: сыноо, төлөм же жазылуу мөөнөтү болгон компанияга берилбейт. Акылуу мөөнөт сыноодон кийин башталат.'],
	'Trial with which tariff' => ['kz' => 'Сынақ қай тарифпен', 'en' => 'Trial with which tariff', 'ru' => 'Пробный период на каком тарифе', 'uz' => 'Sinov qaysi tarif bilan', 'ky' => 'Сыноо кайсы тариф менен'],
	'without tariff' => ['kz' => 'тарифсіз', 'en' => 'without tariff', 'ru' => 'без тарифа', 'uz' => 'tarifsiz', 'ky' => 'тарифсиз'],
	'Archive' => ['kz' => 'Архив', 'en' => 'Archive', 'ru' => 'Архив', 'uz' => 'Arxiv', 'ky' => 'Архив'],
