	'Return from archive' => ['kz' => 'Архивтен шығару', 'en' => 'Return from archive', 'ru' => 'Вернуть из архива', 'uz' => 'Arxivdan chiqarish', 'ky' => 'Архивден чыгаруу'],
	'Moved to archive' => ['kz' => 'Архивке салынды', 'en' => 'Moved to archive', 'ru' => 'Перемещено в архив', 'uz' => 'Arxivga o\'tkazildi', 'ky' => 'Архивге салынды'],
	'Returned from archive' => ['kz' => 'Архивтен шығарылды', 'en' => 'Returned from archive', 'ru' => 'Возвращено из архива', 'uz' => 'Arxivdan chiqarildi', 'ky' => 'Архивден чыгарылды'],
	'Move this company to the archive? It disappears from lists and stats. Data is not deleted.' => ['kz' => 'Компанияны архивке саламыз ба? Тізім мен есептен жасырылады, деректері өшпейді.', 'en' => 'Move this company to the archive? It disappears from lists and stats. Data is not deleted.', 'ru' => 'Переместить компанию в архив? Она скроется из списков и статистики. Данные не удаляются.', 'uz' => 'Kompaniyani arxivga o\'tkazamizmi? Ro\'yxat va hisobotdan yashiriladi, ma\'lumotlari o\'chmaydi.', 'ky' => 'Компанияны архивге салабызбы? Тизме жана эсептен жашырылат, маалыматтары өчпөйт.'],
	'Yes' => ['kz' => 'Иә', 'en' => 'Yes', 'ru' => 'Да', 'uz' => 'Ha', 'ky' => 'Ооба'],
	'No' => ['kz' => 'Жоқ', 'en' => 'No', 'ru' => 'Нет', 'uz' => 'Yo\'q', 'ky' => 'Жок'],
	'Shared by all companies: they pick Economy, Standard or Premium for a dish.' => ['kz' => 'Барлық компанияға ортақ: компания тағамына Эконом, Стандарт не Премиум нұсқасын таңдайды.', 'en' => 'Shared by all companies: they pick Economy, Standard or Premium for a dish.', 'ru' => 'Общие для всех компаний: компания выбирает для блюда Эконом, Стандарт или Премиум.', 'uz' => 'Barcha kompaniyalar uchun umumiy: kompaniya taomga Ekonom, Standart yoki Premium tanlaydi.', 'ky' => 'Бардык компанияларга жалпы: компания тамакка Эконом, Стандарт же Премиум тандайт.'],
	'g' => ['kz' => 'г', 'en' => 'g', 'ru' => 'г', 'uz' => 'g', 'ky' => 'г'],
	'Templates' => ['kz' => 'Шаблондар', 'en' => 'Templates', 'ru' => 'Шаблоны', 'uz' => 'Shablonlar', 'ky' => 'Шаблондор'],
	'AI suggestions' => ['kz' => 'ЖИ ұсыныстары', 'en' => 'AI suggestions', 'ru' => 'Предложения ИИ', 'uz' => 'SI takliflari', 'ky' => 'ЖИ сунуштары'],
	'All categories' => ['kz' => 'Барлық санат', 'en' => 'All categories', 'ru' => 'Все категории', 'uz' => 'Barcha toifalar', 'ky' => 'Бардык категориялар'],
