	'Amounts: kg items in grams, l items in ml, pcs in pieces. Columns show the number of ingredients and the weight of one portion.' => ['kz' => 'Мөлшер: кг құрам граммен, л құрам мл-мен, шт данамен. Бағандарда құрам саны және бір порция салмағы.', 'en' => 'Amounts: kg items in grams, l items in ml, pcs in pieces. Columns show the number of ingredients and the weight of one portion.', 'ru' => 'Количество: кг в граммах, л в мл, шт в штуках. В колонках число ингредиентов и вес одной порции.', 'uz' => 'Miqdor: kg grammda, l ml da, dona donada. Ustunlarda tarkib soni va bir porsiya vazni.', 'ky' => 'Өлчөм: кг граммда, л млде, даана даанада. Мамычаларда курам саны жана бир порциянын салмагы.'],
	'Claude is not connected: no ANTHROPIC_API_KEY in the admin config/ai.php' => ['kz' => 'Claude қосылмаған: админдегі config/ai.php ішінде ANTHROPIC_API_KEY жоқ', 'en' => 'Claude is not connected: no ANTHROPIC_API_KEY in the admin config/ai.php', 'ru' => 'Claude не подключён: в config/ai.php админки нет ANTHROPIC_API_KEY', 'uz' => 'Claude ulanmagan: admin config/ai.php da ANTHROPIC_API_KEY yo\'q', 'ky' => 'Claude туташкан эмес: админдеги config/ai.php ичинде ANTHROPIC_API_KEY жок'],
	'Ready to review' => ['kz' => 'Тексеруге дайын', 'en' => 'Ready to review', 'ru' => 'Готово к проверке', 'uz' => 'Tekshirishga tayyor', 'ky' => 'Текшерүүгө даяр'],
	'Companies see a suggestion only after you approve it.' => ['kz' => 'Компаниялар ұсынысты сіз бекіткен соң ғана көреді.', 'en' => 'Companies see a suggestion only after you approve it.', 'ru' => 'Компании увидят предложение только после вашего утверждения.', 'uz' => 'Kompaniyalar taklifni siz tasdiqlagandan keyin ko\'radi.', 'ky' => 'Компаниялар сунушту сиз бекиткенден кийин гана көрөт.'],
	'Dishes without a template' => ['kz' => 'Шаблоны жоқ тағамдар', 'en' => 'Dishes without a template', 'ru' => 'Блюда без шаблона', 'uz' => 'Shabloni yo\'q taomlar', 'ky' => 'Шаблону жок тамактар'],
	'Find recipes with AI' => ['kz' => 'ЖИ-мен граммовка табу', 'en' => 'Find recipes with AI', 'ru' => 'Найти граммовку с ИИ', 'uz' => 'SI bilan grammovka topish', 'ky' => 'ЖИ менен граммовка табуу'],
	'Every dish in our companies already has a template.' => ['kz' => 'Компаниялардағы барлық тағамның шаблоны бар.', 'en' => 'Every dish in our companies already has a template.', 'ru' => 'У всех блюд компаний уже есть шаблон.', 'uz' => 'Kompaniyalardagi barcha taomlarning shabloni bor.', 'ky' => 'Компаниялардагы бардык тамактын шаблону бар.'],
	'Dishes from active companies that no template matches (sets, combos and drinks are skipped). Tick dishes: AI searches the internet for typical recipes and makes 3 variants. You review them above before companies see them.' => ['kz' => 'Архивте емес компаниялардағы ешбір шаблонға сәйкес келмейтін тағамдар (сет, комбо, сусын кірмейді). Белгілеңіз: ЖИ интернеттен әдеттегі рецептті тауып, 3 нұсқа жасайды. Компанияларға көрсетпес бұрын жоғарыда тексересіз.', 'en' => 'Dishes from active companies that no template matches (sets, combos and drinks are skipped). Tick dishes: AI searches the internet for typical recipes and makes 3 variants. You review them above before companies see them.', 'ru' => 'Блюда активных компаний, которым не подходит ни один шаблон (сеты, комбо и напитки не входят). Отметьте блюда: ИИ найдёт в интернете типичные рецепты и сделает 3 варианта. Перед показом компаниям вы проверяете их выше.', 'uz' => 'Arxivda bo\'lmagan kompaniyalardagi hech bir shablonga mos kelmaydigan taomlar (set, kombo, ichimlik kirmaydi). Belgilang: SI internetdan odatiy retseptni topib, 3 variant tuzadi. Kompaniyalarga ko\'rsatishdan oldin yuqorida tekshirasiz.', 'ky' => 'Архивде эмес компаниялардагы эч бир шаблонго туура келбеген тамактар (сет, комбо, суусундук кирбейт). Белгилеңиз: ЖИ интернеттен кадимки рецептти таап, 3 вариант жасайт. Компанияларга көрсөтүүдөн мурун жогоруда текшересиз.'],
	'Menu category' => ['kz' => 'Мәзір санаты', 'en' => 'Menu category', 'ru' => 'Категория меню', 'uz' => 'Menyu toifasi', 'ky' => 'Меню категориясы'],
	'Enter the title' => ['kz' => 'Атауын жазыңыз', 'en' => 'Enter the title', 'ru' => 'Введите название', 'uz' => 'Nomini yozing', 'ky' => 'Атын жазыңыз'],
